/* Tier One: NST 115 exam prep. Study answers for every item on the instructor's review sheets
   (Unit Exams 1-4, Quizzes 4-14) and the Linux unit (Days 1-3, Top 25 commands, command-line lab).
   Each term: t = item as it appears on the review sheet, d = one-line definition (used by the practice exam),
   a = study answer (markdown-lite, "- " lines are bullets), s = source: 'b<ch>' book chapter, 'class' slides/handouts,
   'gen' general knowledge to double-check against class notes. */
'use strict';
const COURSE = { terms: {}, decks: [] };
function T(id, t, d, a, s) { COURSE.terms[id] = { id, t, d, a, s }; }

/* ---------- Chapters 1-3 (Unit Exam 1) ---------- */
T('pchc', 'PC Health Check', 'Microsoft app that tests whether a PC meets Windows 11\'s hardware requirements.', ['Free Microsoft app that checks a PC against the Windows 11 requirements (TPM 2.0, Secure Boot, supported CPU, RAM, storage) and says what fails.'], 'b2');
T('cortana', 'Cortana', 'Microsoft\'s voice assistant, installed as a separate app in Windows 11.', ['Microsoft\'s voice assistant. In Windows 11 it\'s just a provisioned app, **no longer tied to Windows Search** like it was in early Windows 10. Microsoft has since retired it.'], 'b6');
T('parts4', 'The four partition names and sizes of a newly formatted Windows 11 disk', 'EFI system (~100 MB), MSR (16 MB, hidden), primary NTFS (rest), recovery (~600 MB).', ['- **EFI system partition**, about **100 MB**, FAT32: boot files and the boot loader',
  '- **MSR (Microsoft Reserved)**, usually **16 MB**, **hidden** (only DiskPart sees it): sits between EFI and primary; used for jobs like converting basic to dynamic disk',
  '- **Primary partition (C:)**, **NTFS**, the rest of the disk: Windows, the paging file, all user profiles',
  '- **Recovery partition**, about **600 MB** (the book\'s example is 604 MB), NTFS: lets the PC boot for repair'], 'b2');
T('fexp', 'File Explorer', 'The Windows app for browsing and managing files and folders (Windows key+E).', ['The file manager. Open with **Windows key+E**. Navigation pane, address bar, command bar, details/preview panes and tabs.'], 'b9');
T('upg3', 'The three primary methods/tools when upgrading from Windows 10 to 11', 'Installation Assistant, Media Creation Tool (bootable USB), and the ISO disk image.', ['From the Download Windows 11 page:', '- **Windows 11 Installation Assistant**: checks compatibility, downloads and upgrades in place (Windows 10 version 2004 or later)', '- **Media Creation Tool**: builds a bootable USB (8 GB+)', '- **Disk image (ISO)**: mount it as a virtual DVD or copy it to USB', 'Windows Update can also offer the upgrade.'], 'b2');
T('edge', 'Microsoft Edge', 'Windows\' default browser, built on the Chromium engine.', ['The default browser, built on **Chromium** (same engine as Chrome). Has IE mode for old sites, profiles, tracking prevention and InPrivate.'], 'b7');
T('minreq', 'The minimum processor, RAM, & storage system requirements', '1 GHz 2-core 64-bit CPU, 4 GB RAM, 64 GB storage.', ['- **CPU:** 1 GHz+, **2+ cores**, 64-bit, on the supported list', '- **RAM: 4 GB**', '- **Storage: 64 GB**', 'Also TPM 2.0, UEFI with Secure Boot, DirectX 12 graphics.'], 'b2');
T('tmpfold', 'The name and function of the temporary folders created during a Windows upgrade', '$Windows.~BT (setup files), $Windows.~WS (Media Creation Tool), Windows.old (old install for rollback).', ['- **C:\\$Windows.~BT** (hidden): files Setup uses during the upgrade', '- **C:\\$Windows.~WS** (hidden): created by the Media Creation Tool', '- **C:\\Windows.old** (not hidden): the previous Windows install, kept so you can **roll back** (10 days) and recover files'], 'b2');
T('peek', 'Show/hide (a.k.a Peek)', 'Hover or click the far-right corner of the taskbar to see or show the desktop.', ['The sliver at the **far-right end of the taskbar**. Click it (or **Windows key+D**) to show the desktop; with Peek on, hovering there makes windows transparent so you can glance at the desktop. **Windows key+,** peeks.'], 'b3');
T('snapshot', 'Snapshot', 'A saved point-in-time state of a virtual machine you can roll back to.', ['A saved **point-in-time copy of a virtual machine** (Hyper-V calls it a **checkpoint**). Take one before a risky change; **revert** to undo it. Not a full backup.'], 'b17');
T('taskview', 'Task view', 'Shows all open windows and virtual desktops (Windows key+Tab).', ['**Windows key+Tab**: shows every open window and your **virtual desktops**. Ctrl+Windows key+D makes a new desktop.'], 'b3');
T('jumplist', 'Jump list', 'Right-click menu on a taskbar or Start app with its recent and pinned files and tasks.', ['**Right-click** an app on the taskbar (or Start) to see its **recent/pinned files and common tasks**.'], 'b3');
T('vdi', '.vdi file type', 'VirtualBox Disk Image: the virtual hard disk file used by Oracle VirtualBox.', ['**VirtualBox Disk Image**: Oracle VirtualBox\'s virtual hard disk file. (Hyper-V uses .vhd/.vhdx; VMware uses .vmdk.)'], 'gen');
T('vmadv', 'The list of advantages of using virtual machines', 'Run several OSes on one PC, isolate and test safely, snapshots, easy to copy/move, saves hardware.', ['- Run **multiple operating systems** on one physical PC', '- **Isolation**: test software, updates or malware without risking the host', '- **Snapshots/checkpoints** to roll back instantly', '- **Portable**: a VM is files you can copy, export or move', '- **Saves money and hardware**: fewer physical machines', '- Easy labs for learning (like your Linux VM)'], 'b17');
T('wu', 'Windows Update', 'The service that delivers quality, feature, driver and security intelligence updates.', ['Settings > Windows Update. Delivers **quality** (monthly), **feature** (yearly), **driver**, and **security intelligence** (Defender definition) updates. Pause, active hours, update history and advanced options live here.'], 'b12');
T('oem', 'OEM and how it applies to retailer-offered Windows licenses', 'Original Equipment Manufacturer: a license preinstalled by the PC maker and tied to that PC.', ['**Original Equipment Manufacturer** (the PC maker: Dell, HP...). An **OEM license** comes preinstalled, its key is embedded in firmware, and it is **tied to that one PC**: it can\'t be moved to a new computer. **Retail** licenses can be transferred.'], 'b2');
T('snap', 'Snap', 'Tiling windows into halves or quarters of the screen by dragging to edges or using layouts (Windows key+arrow / Z).', ['Arrange windows side by side: **drag to an edge**, **Windows key+arrow**, or hover the Maximize button / **Windows key+Z** for **Snap layouts**. Snap groups remember the arrangement.'], 'b3');
T('iso', '.iso file', 'A disk image file: an exact copy of a CD/DVD, used for Windows install media and VMs.', ['A **disk image**: a single file holding a whole DVD\'s contents. Double-click to **mount** it as a virtual drive, burn/copy it to USB, or attach it to a VM to install an OS.'], 'b2');
T('dualboot', 'Dual boot', 'Two operating systems installed on separate partitions, chosen from a boot menu.', ['Two (or more) OSes installed on **separate partitions** of the same PC; a **boot menu** at startup lets you pick one. Only one runs at a time (unlike a VM).'], 'b2');
T('smode', 'S mode', 'Locked-down Windows that only runs Microsoft Store apps.', ['A locked-down mode (often on low-cost OEM Home PCs): **only Microsoft Store apps** can be installed; no legacy desktop apps, and even **Cmd.exe and PowerShell are blocked**. More stable and secure; switching out is free but one-way.'], 'b5');
T('biosuefi', 'BIOS & UEFI', 'Firmware that starts the PC; UEFI is the modern replacement for BIOS (needed for Secure Boot/GPT).', ['Firmware that runs before Windows.', '- **BIOS**: legacy, MBR disks, 2 TB limit, no Secure Boot', '- **UEFI**: modern replacement, **GPT** disks, **Secure Boot**, faster startup, mouse-driven setup. **Windows 11 requires UEFI with Secure Boot capability.**'], 'b2');
T('accttypes', 'The difference between a standard user account, Administrator account, and administrator account', 'Standard = limited; administrator = full rights but UAC asks; built-in Administrator = disabled, never prompted by UAC.', ['- **Standard user**: runs apps, changes own settings; system changes need **admin credentials** (credentials prompt)', '- **administrator** (lowercase, "protected admin"): full control but runs with standard rights until it **consents** to a UAC prompt', '- **Administrator** (capital A, built-in): **disabled by default**, **never gets UAC prompts**, always fully elevated, so it\'s risky'], 'b10');

/* ---------- Chapter 4 ---------- */
T('persimp', 'Why Windows personalization is important to know how to do', 'Techs help users set up comfortable, accessible, productive workspaces and fix display/theme problems.', ['Users ask for it constantly: wallpaper, colors, dark mode, text size, accessibility. A comfortable, accessible desktop improves **productivity and accessibility**, and techs must know where these settings live to help and to troubleshoot.'], 'gen');
T('sync', 'Syncing', 'Signing in with a Microsoft account carries settings (themes, passwords, language) across your PCs.', ['With a **Microsoft account**, Windows **syncs settings across every PC you sign in to**: theme, passwords, language preferences, accessibility and other Windows settings. Turn it on or off in **Settings > Accounts > Windows backup** ("Remember my preferences").'], 'b4');
T('slideshow', 'How to enable the slideshow function (bread crumb trail)', 'Settings > Personalization > Background > Personalize your background: Slideshow > Browse.', ['**Settings > Personalization > Background** > *Personalize your background* = **Slideshow** > **Browse** to pick a picture folder > set "change picture every" interval and shuffle.'], 'b4');
T('spotlight', 'Windows Spotlight', 'Feature that downloads a new Bing image daily for the lock screen or desktop.', ['Automatically shows a **new professional photo from Bing each day** on the **lock screen** (and optionally the desktop), with facts about the image.'], 'b4');
T('wallfold', 'The folder location for Windows wallpaper images', 'C:\\Windows\\Web\\Wallpaper', ['**C:\\Windows\\Web\\Wallpaper** (subfolders by theme). Lock screen images are in C:\\Windows\\Web\\Screen.'], 'gen');
T('theme3p', 'Why downloading third-party theme packs can be dangerous', 'Theme files from unknown sites can carry malware or redirect to malicious content.', ['Theme packs (.themepack/.deskthemepack) from unknown websites can **hide malware**, change settings you didn\'t expect, or point to malicious files. **Get themes only from the Microsoft Store.**'], 'gen');
T('focus', 'Focus Assist', 'Silences notifications during set times or activities (now Do not disturb / Focus).', ['Blocks or limits **notifications** so you can concentrate: priority only, alarms only, or automatic rules (while gaming, presenting, at set hours). In 22H2 it became **Do not disturb** plus **Focus sessions** (Settings > System > Notifications / Focus).'], 'b3');
T('access', 'Accessibility features', 'Narrator, Magnifier, high contrast/contrast themes, text size, mouse pointer, Eye Control, captions...', ['Settings > **Accessibility**:', '- **Narrator** (screen reader, Ctrl+Windows key+Enter)', '- **Magnifier** (Windows key+Plus)', '- **Contrast/High contrast themes**', '- **Text size** and **mouse pointer** size/color', '- **Eye Control** (control the PC with eye tracking)', '- Visual alerts for **sounds**, captions, voice access'], 'b4');
T('dark', 'Dark Mode', 'Color mode that uses dark backgrounds for Windows and apps.', ['Light text on dark backgrounds, set in **Settings > Personalization > Colors** > *Choose your mode* (Windows and apps can be set separately). Easier on the eyes in low light.'], 'b4');
T('lock', 'The Lock Screen', 'The screen shown before sign-in, with a picture, time and app status.', ['What you see when the PC is locked (**Windows key+L**) or before sign-in: background picture (Picture, Slideshow or Spotlight), clock and app status. Set in **Settings > Personalization > Lock screen**.'], 'b4');
T('fit', 'Span, Stretch, Tile, Centered, Fit, Fill', 'Ways a wallpaper image is fitted to the screen; Span stretches one image across all monitors.', ['- **Fill**: fills the screen, crops edges, keeps proportions', '- **Fit**: whole image shown, may leave bars', '- **Stretch**: fills the screen by **distorting** the image', '- **Tile**: repeats the image', '- **Center**: original size in the middle', '- **Span**: **one image stretched across multiple monitors**'], 'b4');
T('themes', 'Themes', 'A bundle of background, accent color, sounds and mouse cursor.', ['A **theme** bundles **background + accent color + sounds + mouse pointer**. Settings > Personalization > Themes. Save your own; get more from the Store.'], 'b4');
T('affinity', 'Affinity', 'Task Manager setting that limits which CPU cores a process can run on.', ['Task Manager > **Details** > right-click a process > **Set affinity**: choose **which processor cores** the process may use.'], 'gen');

/* ---------- Chapter 5 ---------- */
T('compat', 'How to run Compatibility Checker and what it does', 'Search "compatibility" > Run programs made for previous versions of Windows; it fixes old-app problems.', ['Windows watches old apps with the **Program Compatibility Assistant**. To fix one yourself: search **compatibility** > **Run programs made for previous versions of Windows** (the compatibility troubleshooter), or right-click the app > Properties > **Compatibility** tab to run it in an older Windows mode. (Before upgrading, **PC Health Check** checks the hardware.)'], 'b5');
T('apptypes', 'The four principal app types from Windows\' perspective', 'Legacy desktop (Win32), Windows/Store apps, Progressive Web Apps, Android apps.', ['- **Legacy desktop apps (Win32)**: classic installers, broad system access', '- **Windows apps**: packaged, **sandboxed**, usually from the Store', '- **Progressive Web Apps (PWAs)**: websites installed as apps', '- **Android apps** (Windows Subsystem for Android; retired in 2025)', '(The book groups the first three; your class adds Android.)'], 'b5');
T('store3', 'The three requirements a Microsoft-certified app must meet to be in the MS Store', 'Passes security checks, installs silently, and uninstalls cleanly.', ['Store certification checks that the app:', '1. **Passes security checks** (no malware/unwanted software)', '2. **Installs silently**, with no user activity required', '3. **Uninstalls cleanly**, leaving no files, folders or stray registry entries'], 'b5');
T('uacwhy', 'Reasons a UAC prompt will appear (why elevated permissions are needed)', 'Changes to system-wide settings or files in Windows/Program Files: installing apps/drivers, firewall, accounts, registry...', ['Anything that changes **system-wide settings** or files in **C:\\Windows** or **C:\\Program Files**:', '- Installing/uninstalling most desktop apps and **drivers**', '- Changing **Windows Defender Firewall**, **UAC** or **Windows Update** settings', '- **Adding/removing user accounts** or changing account type', '- Running **Task Scheduler**, **editing the registry**', '- Restoring system files; viewing **another user\'s files**', 'A **shield icon** on a button means it will prompt.'], 'b12');
T('tm', 'How to get to Task Manager and what each tab does', 'Ctrl+Shift+Esc; tabs: Processes, Performance, App history, Startup apps, Users, Details, Services.', ['Open with **Ctrl+Shift+Esc** (or Ctrl+Alt+Del, or right-click Start).', '- **Processes**: running apps/background processes; End task', '- **Performance**: live CPU, memory, disk, network, GPU graphs', '- **App history**: resource use of Store apps over time', '- **Startup apps**: enable/disable apps that start at sign-in, with impact rating', '- **Users**: who\'s signed in and what they use', '- **Details**: every process by .exe name, PID; priority, **affinity**', '- **Services**: start/stop services; link to the Services console'], 'b14');
T('tmkey', 'Task Manager keyboard shortcut', 'Ctrl+Shift+Esc', ['**Ctrl+Shift+Esc** opens it directly. (Ctrl+Alt+Del then Task Manager also works.)'], 'b5');
T('autoplay', 'Autoplay', 'Decides what happens automatically when you insert a USB drive or memory card.', ['Chooses the action when you plug in **removable drives or memory cards** (open folder, import photos, take no action, ask me). **Settings > Bluetooth & devices > AutoPlay**. Turning it off is a security best practice.'], 'b5');
T('backcompat', 'Backwards compatibility', 'Ability of Windows 11 to run apps written for older Windows versions.', ['Windows 11 can **run software written for older versions** of Windows. It was designed with backward compatibility as a "prime directive" so businesses can keep apps they\'ve relied on for years.'], 'b5');
T('startup', 'Two locations to enable/disable apps that start when your PC starts', 'Task Manager > Startup apps, and Settings > Apps > Startup.', ['1. **Task Manager > Startup apps** (Enable/Disable, shows startup impact)', '2. **Settings > Apps > Startup** (toggle switches)', '(Also: the Startup folder, `shell:startup`.)'], 'b5');

/* ---------- Chapter 6 ---------- */
T('sysapps', 'Windows System apps', 'Apps integral to Windows that can\'t be uninstalled (Settings, Start, Search...); in Windows\\SystemApps.', ['Part of the OS and **can\'t be uninstalled**. Examples: **Settings** (Immersive Control Panel), the **Start** menu host, **Search**, Accounts Control Host, Credential Dialog Host, Print Dialog. Stored in **C:\\Windows\\SystemApps**.'], 'b6');
T('provapps', 'Provisioned apps', 'Apps installed into every user account the first time it signs in.', ['Installed **into each user account the first time it signs in** (Store, Calculator, Photos, Clipchamp, Snipping Tool...). Some can be uninstalled in Settings > Apps. List them: `Get-AppxProvisionedPackage -Online`.'], 'b6');
T('instapps', 'Installed apps', 'Apps added at first sign-in by the Content Delivery Manager, often third-party (TikTok, Disney+); all removable.', ['Added when a new account signs in, through the **Windows Content Delivery Manager**: often **third-party** apps and trials (TikTok, Facebook, Amazon Prime, Disney+) on Home/Pro; productivity apps on Enterprise. **All can be uninstalled** in Settings > Apps > Installed apps.'], 'b6');
T('connexp', 'Windows Connected Experience Apps', 'Apps that link Windows to your phone, other devices and cloud accounts (Phone Link, OneDrive, Teams...).', ['Apps that **connect your PC to other devices and online services**: **Phone Link** (your phone), **OneDrive** (files), **Microsoft Teams** chat, Outlook/Mail, and "continue on other devices" features. *Check your class list for the exact names your instructor uses.*'], 'gen');
T('provcat', 'Provisioned apps category examples', 'Information, Communications & productivity, Entertainment, Creative tools, Utilities.', ['The book\'s five categories:', '- **Information:** Cortana, Feedback Hub, Get Help, Get Started, Maps, News, Weather', '- **Communications & productivity:** Mail & Calendar, To Do, Teams, Phone Link, Office, Sticky Notes', '- **Entertainment:** Media Player, Movies & TV, Solitaire, Xbox', '- **Creative tools:** Clipchamp, Photos, Paint, Voice Recorder', '- **Utilities:** Alarms & Clock, Calculator, Camera, Notepad, Power Automate, **Quick Assist**, Snipping Tool, Windows Terminal'], 'b6');
T('snip', 'Snipping Tool shortcuts', 'Windows key+Shift+S snip; PrtScn; Windows key+PrtScn saves a file; Alt+PrtScn active window.', ['- **Windows key+Shift+S**: snip overlay (rectangle, freeform, window, full screen), copies to clipboard', '- **PrtScn**: full screen to clipboard (or opens Snipping Tool if set)', '- **Windows key+PrtScn**: saves a PNG to **Pictures\\Screenshots**', '- **Alt+PrtScn**: active window only', '- **Windows key+Shift+R**: screen recording (newer builds)'], 'b6');
T('quickassist', 'Quick Assist', 'Built-in remote help app: the helper gets a code from the user and can view or control the PC.', ['Built-in **remote support** app (**Windows key+Ctrl+Q**). The **helper** signs in and gets a **security code**; the person being helped enters it and allows **view only** or **full control**. Beware scammers who ask you to open it.'], 'b6');
T('teamsnav', 'The Teams Navigation Bar and its icons', 'The vertical bar down the left side of Teams: Activity, Chat, Teams, Calendar, Calls, Files, plus more apps.', ['The **vertical bar on the left side** of Teams. Top to bottom:', '- **Activity** (bell icon): your feed of @mentions, replies, reactions and alerts', '- **Chat** (speech bubble): one-on-one and group chats, outside of teams', '- **Teams** (group of people): the teams you belong to and their **channels**', '- **Calendar**: your meetings; schedule a new meeting or **Meet now**', '- **Calls** (phone): call people, contacts, call history, voicemail', '- **Files** (document): files shared across your teams and OneDrive', '- **"..." / Apps**: add more apps to the bar', 'Source: the class video (Kevin Stratvert, *Microsoft Teams Tutorial in 10 min*), which covers them at 1:28 and 6:15 to 9:04.'], 'class');
T('tv_teams', 'Teams and channels (video)', 'Join or create a team; each team has channels where posts and conversations happen.', ['From the video: **join** a team with a code or **create** one (from scratch or a template; private or public), then **edit team settings**. Each team has **channels** (General plus ones you add) holding **Posts** (threaded conversations: reply, @mention, react, attach files) and **Files**. **Show/hide** and **pin** channels to organize them.'], 'class');
T('tv_meet', 'Scheduling and joining a meeting (video)', 'Calendar > New meeting (or Meet now); join from the calendar or a link, then use the meeting controls.', ['**Calendar** > **New meeting** (title, attendees, time, channel) or **Meet now**. Join from the calendar or a link, choose camera/mic settings, then use the meeting bar: camera, mic, share screen, chat, participants, raise hand, leave.'], 'class');
T('teamsdef', 'Teams as the default Windows comm app', 'Microsoft Teams (free) replaced Skype as the built-in chat/call app in Windows 11.', ['**Microsoft Teams** replaced **Skype** as the built-in communications app (chat, audio and video calls). The free personal Teams is separate from the work/school version.'], 'b6');
T('cattlist', 'Examples from each application category', 'Information / Communications / Entertainment / Creative tools / Utilities, with example apps.', ['Keep the five-category list handy (see **Provisioned apps category examples**).'], 'b6');
T('articles', 'Assigned articles: recommendations for productivity and browser options', 'At least two test questions come from the assigned reading on productivity and browser choices.', ['At least two test questions come from the assigned articles. The **browser** article (PCMag\'s best-browser picks) is covered in Quiz 7: see **The ranking of browser types from the article** and the article items after it. If there was a separate **productivity** article, it isn\'t in the materials here.'], 'class');

/* ---------- Chapter 7 ---------- */
T('dns', 'DNS', 'Domain Name System: translates names like google.com into IP addresses.', ['**Domain Name System**: the internet\'s phone book. Turns a name (google.com) into an **IP address**. First step when you type a URL.'], 'gen');
T('tcp', 'TCP', 'Transmission Control Protocol: reliable, connection-based delivery with handshake and retransmission.', ['**Transmission Control Protocol**: **connection-oriented** and **reliable** (3-way handshake, ordered, resends lost packets). Used for web pages, email, file transfer. Layer 4.'], 'gen');
T('udp', 'UDP', 'User Datagram Protocol: fast, connectionless, no delivery guarantee.', ['**User Datagram Protocol**: **connectionless**, fast, **no guarantee** of delivery or order. Used for streaming, gaming, voice, DNS lookups. Layer 4.'], 'gen');
T('http', 'HTTP', 'Hypertext Transfer Protocol: the request/response rules browsers use to get web pages (port 80; encrypted version uses 443).', ['**Hypertext Transfer Protocol**: the request/response rules browsers use to get web pages (GET, POST; status codes like 200 and 404). **HTTPS** adds TLS encryption. Port 80/443. Layer 7.'], 'gen');
T('cookie', 'Cookie', 'Small text file a website stores in your browser to remember you (logins, carts, tracking).', ['A small piece of data a site saves **in your browser** to remember you: sign-in sessions, cart, preferences. **Third-party cookies** are used for tracking across sites. Clear with Ctrl+Shift+Delete.'], 'b7');
T('dom', 'DOM', 'Document Object Model: the tree of objects the browser builds from a page\'s HTML.', ['**Document Object Model**: the browser **parses the HTML** into a **tree of nodes** (elements, text). JavaScript reads and changes the page through the DOM.'], 'gen');
T('cssom', 'CSSOM', 'CSS Object Model: the tree of style rules the browser builds from the CSS.', ['**CSS Object Model**: the browser parses the **CSS** into a tree of style rules, the styling counterpart of the DOM.'], 'gen');
T('rtree', 'Render Tree', 'DOM + CSSOM combined: only the visible elements with their computed styles.', ['**DOM + CSSOM combined** into the tree of **visible** elements with their styles (hidden elements like display:none are left out). Used for layout and painting.'], 'gen');
T('parsing', 'Parsing', 'Reading HTML/CSS text and turning it into the DOM and CSSOM.', ['The browser **reads the raw HTML and CSS** text and turns it into structured trees (**DOM** and **CSSOM**).'], 'gen');
T('painting', 'Painting', 'Filling in the pixels (text, colors, images, borders) for each element.', ['After layout works out sizes and positions, **painting** fills in the actual **pixels**: text, colors, images, borders, shadows, often on separate layers.'], 'gen');
T('compos', 'Compositing', 'Combining painted layers in the right order to produce the final screen image.', ['The last step: **stacking the painted layers** in the right order (often on the GPU) to make the final image on screen.'], 'gen');
T('osi', 'Layers of the OSI model', '7 Application, 6 Presentation, 5 Session, 4 Transport, 3 Network, 2 Data Link, 1 Physical.', ['Top to bottom: **7 Application** (HTTP, DNS) · **6 Presentation** (encryption, formats) · **5 Session** · **4 Transport** (TCP/UDP) · **3 Network** (IP, routers) · **2 Data Link** (MAC, switches) · **1 Physical** (cables, signals).', 'Mnemonic (7→1): **A**ll **P**eople **S**eem **T**o **N**eed **D**ata **P**rocessing.'], 'gen');
T('render', 'Order of operations from web page request to final rendering', 'DNS lookup > TCP (+TLS) > HTTP request > parse HTML/CSS > DOM + CSSOM > render tree > layout > paint > composite.', ['1. **DNS** lookup (name to IP)', '2. **TCP** connection (+TLS for HTTPS)', '3. **HTTP** request and response (HTML)', '4. **Parse** HTML into the **DOM**, CSS into the **CSSOM** (JavaScript can change both)', '5. Combine into the **render tree**', '6. **Layout** (sizes and positions)', '7. **Paint** pixels', '8. **Composite** layers onto the screen'], 'gen');
T('rank', 'The ranking of browser types from the article', 'PCMag picks: Chrome (compatibility/speed), Safari (Apple users), Edge (helper features/AI), Firefox (open-source/private), Brave (ad blocking/privacy).', ['PCMag, *Brave, Chrome, Edge, Firefox, or Safari? We Pick the Best Browser*: its **top tested picks, in order**:', '1. **Google Chrome**: best for **compatibility and speed**', '2. **Apple Safari**: best for **Apple users**', '3. **Microsoft Edge**: best for **helper features and AI** (Copilot)', '4. **Mozilla Firefox**: best **open-source, private** option', '5. **Brave**: best for **ad blocking and privacy**', '**Heads up:** the current version (updated May 2026) swapped **Opera** out for Brave. If the copy your class read was older, Opera may be the fifth pick.'], 'class');
T('art_market', 'Browser market share and engines (article)', 'Chrome has about 70% share; most browsers use Chromium; only Firefox and Safari use other engines.', ['- **Chrome** holds about **70%** of worldwide browser share', '- Most browsers now use Google\'s **Chromium** engine (Chrome, Edge, Brave)', '- Only **Firefox and Safari** use non-Chromium engines; **Firefox** is the only fully independent competitor', '- HTML is now a **"living standard"** with no version number; all major browsers are highly compatible'], 'class');
T('art_pwa', 'Which browsers support PWAs (article)', 'Chromium browsers (Brave, Chrome, Edge) support progressive web apps; Firefox and Safari don\'t.', ['**Progressive web apps** (sites like Gmail or Spotify that act like real apps) work in the **Chromium browsers: Brave, Chrome and Edge**. **Firefox and Safari don\'t** (Firefox has a Windows-only taskbar tabs feature; Safari has its own way on macOS).'], 'class');
T('art_privacy', 'Best browsers for privacy (article)', 'Brave and Firefox; they, plus Safari, block third-party tracking cookies by default.', ['- **Brave and Firefox** are the best privacy options', '- **Brave, Firefox and Safari** block **third-party tracking cookies by default**; Chrome and Edge don\'t (but you can turn it on)', '- **Brave and Firefox** include a built-in **VPN** (Firefox: 50 GB free per month)', '- **Brave** is the only one with a **built-in ad blocker** and a **crypto wallet**; it also randomizes your fingerprint', '- Chrome signs you into Google services by default and uses Google\'s ad-interest tracking'], 'class');
T('art_speed', 'Browser speed testing (article)', 'Tested with JetStream, Speedometer and WebXPRT; they all feel fast, Chromium browsers score alike.', ['All browsers feel fast now. PCMag benchmarks with **JetStream**, **Speedometer** and **WebXPRT**. Chromium browsers score about the same; Firefox trails in most tests but does well in WebXPRT. Edge\'s Enhanced Security mode lowers its scores.'], 'class');
T('art_tools', 'Browser tools and AI (article)', 'Vertical tabs, split view and AI assistants in all; Edge Copilot can see pages; Manifest V3 limits blockers in Chromium.', ['- **Vertical tabs** and **split view** in all five', '- All have **AI assistants**; **Edge\'s Copilot** can "see" pages and talk about them in voice mode', '- **Firefox**: edits PDFs, **Containers** (two logins to one site), translation, reading mode', '- Chromium extensions use **Manifest V3**, which weakens ad blockers like **uBlock Origin**; Firefox still runs the full version', '- **AI browsers** (Copilot, ChatGPT Atlas, Comet) are new; PCMag doesn\'t recommend switching to one yet'], 'class');
T('art_ie', 'Replacing Internet Explorer (article)', 'IE support ended June 15, 2022; use Edge, and Edge\'s IE mode for old web apps.', ['**Internet Explorer** lost support on **June 15, 2022**. Microsoft moved to **Edge**; if you still need IE for an old web app, use **IE mode in Edge**.'], 'class');

/* ---------- Chapter 8 ---------- */
T('basic', 'Basic disk', 'Default disk type using standard partitions (primary/extended or GPT partitions).', ['The **default** disk type. Uses ordinary **partitions** (MBR or GPT). Works with every OS and tool. Can be converted to dynamic.'], 'b8');
T('dynamic', 'Dynamic disk', 'Legacy disk type using volumes that can span multiple disks (spanned, striped, mirrored); deprecated.', ['Uses **volumes** instead of partitions: **simple, spanned, striped, mirrored, RAID-5** across disks. **Deprecated**: Microsoft recommends **Storage Spaces** instead. Converting back to basic requires deleting volumes.'], 'b8');
T('simple', 'Simple Volume', 'A volume using space on a single disk.', ['A volume that uses space on **one disk only**. Created in Disk Management with "New Simple Volume". (On dynamic disks it can be extended.)'], 'b8');
T('mounted', 'Mounted drive', 'A volume attached to an empty NTFS folder instead of (or as well as) a drive letter.', ['A volume made available through an **empty folder on an NTFS volume** instead of a drive letter (e.g. C:\\Data opens another disk). Also: **mounting** an ISO/VHD makes it appear as a drive.'], 'b8');
T('errchk', 'Error Checking', 'Drive Properties > Tools > Check: scans for and fixes file system errors (chkdsk).', ['Drive **Properties > Tools > Check**: scans the file system for errors and fixes them. Command-line version: **chkdsk** (`/f` fix, `/r` bad sectors).'], 'b8');
T('gpt', 'GPT', 'GUID Partition Table: modern partition style for UEFI, >2 TB disks, up to 128 partitions.', ['**GUID Partition Table**: modern. Needed for **UEFI** boot, disks **larger than 2 TB**, up to **128 partitions**, keeps a backup partition table. Windows 11 uses it.'], 'b8');
T('mbr', 'MBR', 'Master Boot Record: legacy partition style, 2 TB limit, 4 primary partitions.', ['**Master Boot Record**: legacy (BIOS). **2 TB** maximum, **4 primary partitions** (or 3 + extended). Convert with MBR2GPT.'], 'b8');
T('ntfs', 'NTFS', 'New Technology File System: Windows\' main file system with permissions, encryption, compression.', ['**NTFS**: the Windows standard. **Permissions (ACLs)**, **encryption (EFS/BitLocker)**, compression, journaling for crash recovery, huge files.'], 'b8');
T('cdfs', 'CDFS', 'CD File System (ISO 9660) used for CDs/DVDs.', ['**Compact Disc File System** (ISO 9660): read-only file system for **CDs/DVDs**.'], 'gen');
T('fat32', 'FAT32', 'Older universal file system; 4 GB maximum file size.', ['Old but works everywhere. **4 GB maximum file size**, 32 GB volume limit when formatted in Windows. Used for the **EFI system partition** and small USB sticks.'], 'b8');
T('exfat', 'exFAT', 'Flash-drive file system with no 4 GB file limit, works on Windows and Mac.', ['For **USB drives and SD cards**: **no 4 GB file limit**, works on Windows, Mac, cameras. No NTFS permissions.'], 'b8');
T('optimize', 'Optimize (Optimization)', 'Defragments hard disks and sends TRIM to SSDs, on a weekly schedule.', ['**Optimize Drives** (`dfrgui`): **defragments HDDs** and runs **TRIM on SSDs**. Scheduled **weekly** by default. Never defrag an SSD manually.'], 'b8');
T('sspaces', 'Storage Spaces', 'Pools multiple physical disks into one virtual drive with optional mirroring or parity.', ['Pools several disks into **one virtual drive** with resiliency: **simple** (none), **two-way mirror** (survives 1 failure), **three-way mirror** (2), **parity** (1, more space efficient).'], 'b8');
T('diskmgmt', 'Disk Management', 'GUI console (diskmgmt.msc) to initialize, partition, format and change drive letters.', ['**diskmgmt.msc** (Windows key+X). **Initialize** disks (MBR/GPT), **create/delete/format** volumes, **extend/shrink**, change **drive letters**, mount VHDs.'], 'b8');
T('diskpart', 'DiskPart', 'Command-line disk partitioning tool (list disk, select disk, clean, create partition...).', ['Command-line partitioning (run as admin): `list disk` > `select disk 1` > `clean` > `create partition primary` > `format fs=ntfs quick` > `assign`. Can see the hidden **MSR** partition. Powerful and dangerous.'], 'b8');
T('onedrive', 'OneDrive', 'Microsoft cloud storage that syncs files; Files On-Demand shows online-only vs local files.', ['Microsoft\'s **cloud storage** built into File Explorer. **Files On-Demand**: cloud icon = online-only, green check = local. **Folder backup** syncs Desktop/Documents/Pictures. **Personal Vault** for sensitive files.'], 'b8');
T('location', 'Location (tab)', 'Folder Properties tab used to move a user folder like Documents to another drive.', ['The **Location** tab in a personal folder\'s **Properties** (Documents, Pictures...) lets you **move it to another drive**, and Windows keeps treating it as that folder.'], 'b9');
T('primary', 'Primary Partition', 'Main partition that holds Windows, programs and user files (C:, NTFS).', ['The main **NTFS** partition (**C:**) holding **Windows, the paging file and user profiles**. On MBR a disk can have up to 4 primary partitions.'], 'b2');
T('syspart', 'System Partition', 'The EFI partition with the files needed to start Windows (boot loader).', ['The partition with the files the PC needs to **start**: on UEFI/GPT it\'s the **EFI system partition** (~100 MB, FAT32, boot loader). (Confusingly, Windows itself lives on the *boot* volume, C:.)'], 'b2');
T('msr', 'Microsoft Reserved partition', 'Hidden 16 MB GPT partition reserved for disk management tasks; not shown in Disk Management.', ['**MSR**: required on every **GPT** disk, ~**16 MB**, **hidden** from Disk Management (DiskPart shows it). Reserved for tasks like converting basic to dynamic.'], 'b2');
T('recovpart', 'Recovery partition', 'Small partition holding the Windows Recovery Environment for repairs.', ['Small (~600 MB) partition with the **Windows Recovery Environment (WinRE)**: Startup Repair, System Restore, Reset this PC. PC makers may add their own.'], 'b2');
T('ssd', 'SSD', 'Solid-state drive: flash storage with no moving parts; fast; optimized with TRIM, not defrag.', ['**Solid-state drive**: flash memory, **no moving parts**, much faster than an HDD. Windows optimizes it with **TRIM** instead of defragmenting.'], 'b8');

/* ---------- Chapter 9 ---------- */
T('navpane', 'Navigation Pane', 'Left pane of File Explorer: Home, Quick access, OneDrive, This PC, Network.', ['The **left pane** of File Explorer: Home, Gallery, **Quick access**, OneDrive, **This PC**, Network (and Libraries if shown).'], 'b9');
T('cmdbar', 'Command bar', 'Toolbar at the top of File Explorer: New, cut/copy/paste, rename, share, delete, Sort, View, "...".', ['The **toolbar** under the address bar: **New, Cut, Copy, Paste, Rename, Share, Delete, Sort, View** and **"..."** (more). Replaced the old ribbon.'], 'b9');
T('addrbar', 'Address bar', 'Shows the current path as clickable breadcrumbs; type a path or command there.', ['Shows the current location as **breadcrumbs** (click any part to jump). Click it to type a **path** like C:\\Windows, or even `cmd`.'], 'b9');
T('searchbar', 'Search bar', 'Box in the top right of File Explorer that searches the current folder and subfolders.', ['Top right of File Explorer: searches the **current folder and its subfolders**, using the **index** when available. Accepts filters like `kind:` and `date:`.'], 'b9');
T('details', 'Details Pane', 'Side pane showing a selected file\'s properties/metadata (Alt+Shift+P).', ['Right-side pane showing the selected file\'s **properties and metadata** (size, dates, author, tags) and letting you edit some. Toggle with **Alt+Shift+P**.'], 'b9');
T('quickacc', 'Quick Access', 'Pinned and frequent folders plus recent files for fast navigation.', ['**Pinned and frequently used folders** (and recent files on Home) for one-click access. Right-click a folder > **Pin to Quick access**.'], 'b9');
T('libraries', 'Libraries', 'Virtual folders that combine content from several locations into one view.', ['**Virtual folders** that show files from **several real folders** in one place (Documents, Music, Pictures, Videos). Hidden by default: View > Show > **Libraries**.'], 'b9');
T('winfold', 'Windows (folder)', 'C:\\Windows: the operating system files; protected, changes need admin.', ['**C:\\Windows** (%SystemRoot%): the OS itself, System32, drivers, fonts. **Protected**: changes need admin rights and trigger UAC.'], 'b9');
T('recycle', 'Recycle bin', 'Holds deleted local files until emptied; USB/network deletes and Shift+Delete skip it.', ['Deleted files from **local drives** wait here to be **restored**. **Skipped by:** Shift+Delete, files on **USB flash drives** and **network shares**. Set its size per drive in Properties.'], 'b9');
T('progfiles', 'Program files folders', 'C:\\Program Files (64-bit apps) and C:\\Program Files (x86) (32-bit apps).', ['- **C:\\Program Files**: **64-bit** apps', '- **C:\\Program Files (x86)**: **32-bit** apps', 'Protected: installing there needs admin approval.'], 'b9');
T('searches', 'C:\\Users\\"username"\\Searches', 'The folder where your saved searches (.search-ms files) are stored.', ['Where **saved searches** live, as **.search-ms** files you can reopen to rerun the search.'], 'b9');
T('indexing', 'Indexing', 'Windows Search keeps an index of file names, properties and contents so searches are fast.', ['The **Windows Search** service builds an **index** of file names, properties and contents in indexed locations, so searches are instant. Manage in **Indexing Options** (add locations, **Rebuild**). Classic = user folders; Enhanced = whole PC.'], 'b9');
T('grep', 'GREP', 'Global Regular Expression Print: Linux command that searches text in files for a pattern.', ['**Global Regular Expression Print**: Linux/Unix command that **searches inside files for a text pattern**: `grep "error" logfile.txt`. Windows\' closest equivalents: `findstr` and PowerShell `Select-String`.'], 'class');
T('metadata', 'Metadata', 'Data about a file: author, date taken, tags, rating, dimensions.', ['**Data about data**: author, dates, **tags**, rating, camera info, dimensions. Shown in the **Details pane** and **Properties > Details**; remove it with "Remove Properties and Personal Information".'], 'b9');
T('boolean', 'Boolean Operators', 'AND, OR, NOT used to combine or exclude search terms.', ['**AND** (both terms), **OR** (either), **NOT** (exclude). Must be **CAPITALIZED** in Windows search: `budget AND 2024 NOT draft`. Quotes for exact phrases.'], 'b9');
T('defprof', 'C:\\Windows\\Users\\Default (the Default profile)', 'Hidden template profile copied to create every new user\'s folders.', ['The **hidden Default profile**: a **template** copied to build every new local user\'s profile folders. (Its real path is **C:\\Users\\Default**. Your review sheet writes it as C:\\Windows\\Users\\Default.)'], 'b10');

/* ---------- Chapter 10 ---------- */
T('defacctfold', 'The default user account folders', 'Desktop, Documents, Downloads, Music, Pictures, Videos, Contacts, Favorites, Links, Saved Games, Searches, OneDrive, AppData.', ['Every profile (C:\\Users\\name) gets: **Desktop, Documents, Downloads, Music, Pictures, Videos, Contacts, Favorites, Links, Saved Games, Searches, OneDrive**, plus the hidden **AppData**.'], 'b9');
T('compmgmt', 'Computer Management Console', 'compmgmt.msc: one MMC console with Event Viewer, Local Users and Groups, Device Manager, Disk Management, Services...', ['**compmgmt.msc** (Windows key+X). An MMC console bundling **System Tools** (Task Scheduler, **Event Viewer**, Shared Folders, **Local Users and Groups**, Performance, **Device Manager**), **Storage** (**Disk Management**) and **Services**.', 'Add/edit users: **Local Users and Groups > Users** > right-click > **New User** or Properties (Pro and up).'], 'b16');
T('sid', 'SID', 'Security Identifier: the unique ID Windows uses for each account; a deleted account\'s ID is gone for good.', ['**Security Identifier**: the unique number Windows really uses for each account and group (permissions are assigned to SIDs, not names). Find yours with **`whoami /user`**. **Delete accounts with care:** a recreated account with the same name gets a **new SID**, so it **loses** its old files\' permissions, encryption keys and settings.'], 'b10');
T('uac', 'UAC', 'User Account Control: runs everything with standard rights and asks before elevating.', ['**User Account Control** keeps even admins running with **standard rights** until a task needs more. Then it shows a **consent** prompt (admins) or **credentials** prompt (standard users) on the **secure desktop** (screen dims). Slider has 4 levels; default = notify when apps make changes.'], 'b12');
T('biosvc', 'Windows biometric authentication service', 'Windows Biometric Service: powers Windows Hello face and fingerprint sign-in.', ['The **Windows Biometric Service** handles fingerprint and face data for **Windows Hello**. Biometric data stays **on the device** (not sent to Microsoft) and needs compatible hardware (IR camera, fingerprint reader).'], 'b10');
T('hiddentmpl', 'Name/location of the hidden folder containing template folders for new local accounts', 'C:\\Users\\Default', ['**C:\\Users\\Default**: the hidden **Default** profile, copied for every new local account.'], 'b10');
T('appdata', 'Location and function of the AppData folder', 'Hidden C:\\Users\\name\\AppData (Local, LocalLow, Roaming): per-user app settings and data.', ['**C:\\Users\\username\\AppData** (hidden; `%appdata%` jumps to Roaming). Apps store **per-user settings, caches and data** there:', '- **Roaming**: follows the user between domain PCs', '- **Local**: this PC only (caches, big files)', '- **LocalLow**: low-trust apps (sandboxed)'], 'b9');
T('kiosk', 'The kiosk function and how to access it', 'Assigned access: one account runs one full-screen app; Settings > Accounts > Other users > Set up a kiosk.', ['**Assigned access**: one designated account can run **only one app**, full screen, starting automatically. Exit only with **Ctrl+Alt+Del**. Uses: public kiosk, point of sale, a child\'s game. **Settings > Accounts > Other users > Set up a kiosk > Get started.**'], 'b10');
T('polp', 'Principle of Least Privilege', 'Give users only the rights they need to do their job, nothing more.', ['Give every account **only the access it needs**. Daily work in a **standard account**; use admin only when required. Limits damage from mistakes and malware.'], 'b10');
T('pwbest', 'MS best practices for password security', 'Long unique passwords or passphrases, a password manager, MFA, Windows Hello/PIN, never reuse.', ['- **Long** (passphrases), **unique** for every account, **never reused**', '- Use a **password manager** (Edge can generate them)', '- Turn on **multifactor authentication**', '- Prefer **Windows Hello / PIN** or passwordless sign-in', '- Don\'t share them; change after a breach (Password Monitor)'], 'b10');
T('privperm', 'Privileges vs Permissions', 'Privileges = system-wide rights for an account; permissions = access rights to a specific object.', ['- **Privileges (rights)**: what an account can do **to the system** (shut down, change the time, back up files, install drivers)', '- **Permissions**: what an account can do **to a specific object** (read/write/modify a file, folder, printer, registry key), set in its **ACL**'], 'b10');
T('permissions', 'Permissions', 'Access rights on an object (Read, Write, Modify, Full Control) set in its ACL.', ['Rules on a **file, folder, printer or registry key** saying who can **Read, Write, Modify, Read & Execute, or have Full Control**. Stored in the object\'s **ACL**; **Deny beats Allow**. Share + NTFS permissions: the **most restrictive** wins.'], 'b10');
T('defaccts', 'Default Windows accounts created at installation', 'Administrator (disabled), Guest (disabled), DefaultAccount, WDAGUtilityAccount, plus your first (admin) account.', ['- **Administrator**: built-in, **disabled** by default', '- **Guest**: **disabled**', '- **DefaultAccount**: system-managed, disabled', '- **WDAGUtilityAccount**: used by Defender Application Guard', '- Plus **the first account you create**, which joins the **Administrators** group'], 'gen');

/* ---------- Chapter 11 ---------- */
T('rdp', 'How to enable RDP in Windows 11', 'Settings > System > Remote Desktop > On (Pro or higher); connect with mstsc; port 3389.', ['**Settings > System > Remote Desktop > On** (needs **Pro, Enterprise or Education**: Home can only connect out). Keep **Network Level Authentication** on. Connect with **mstsc** (Remote Desktop Connection). Uses **TCP port 3389**.'], 'b11');
T('wpa', 'WPA, WEP, WPA2, & WPA3', 'Wi-Fi security standards; WEP is broken, WPA weak (TKIP), WPA2 uses AES, WPA3 strongest.', ['Weakest to strongest:', '- **WEP**: broken, crackable in minutes, never use', '- **WPA**: TKIP, outdated', '- **WPA2**: **AES**, the common standard (Personal = shared key; **Enterprise = 802.1X/RADIUS**)', '- **WPA3**: newest and **strongest** (SAE handshake, better protection against password guessing)'], 'b11');
T('advshare', 'Advanced Sharing', 'Sharing dialog where you set a share name, limit simultaneous users and set share permissions (Read/Change/Full Control).', ['Folder **Properties > Sharing > Advanced Sharing**: check **Share this folder**, set the **share name**, **limit simultaneous users**, and set **share permissions** (Read, Change, Full Control). NTFS permissions still apply too.'], 'b11');
T('sharewiz', 'Sharing Wizard', 'Simple step-by-step sharing (Share with > Specific people) that sets permissions for you.', ['The **simple** way to share: right-click > **Give access to > Specific people**, pick users and **Read** or **Read/Write**; Windows sets both share and NTFS permissions for you. Turn it off in File Explorer **Folder Options > View** to use Advanced Sharing.'], 'b11');
T('netdisc', 'Network discovery & File and Print Sharing', 'Settings that let this PC see/be seen on the network and share files and printers (Private networks).', ['- **Network discovery**: this PC can **see other devices and be seen** on the network', '- **File and printer sharing**: lets others **access shared folders and printers** on this PC', 'Both are **on for Private** networks and **off for Public**. (Settings > Network & internet > Advanced network settings > Advanced sharing settings)'], 'b11');
T('netprof', 'Public, Private, & Domain network types', 'Public = untrusted, discovery off; Private = home/work, discovery on; Domain = set automatically on a company domain.', ['- **Public**: untrusted (coffee shop, airport): **discovery and sharing off**, strictest firewall. **Default** for new networks', '- **Private**: trusted home/small office: **discovery and sharing allowed**', '- **Domain**: applied **automatically** when the PC is on its Active Directory domain; firewall controlled by IT/Group Policy'], 'b11');
T('ip4', 'The four methods of obtaining an IP address on a Windows PC', 'DHCP, APIPA (169.254.x.x), static IP, and alternate configuration.', ['1. **DHCP** (default): a server/router hands out the address automatically', '2. **APIPA**: no DHCP server found, so Windows picks **169.254.x.x**', '3. **Static**: typed in manually; never changes', '4. **Alternate configuration**: a backup static address used when DHCP isn\'t available (IPv4 Properties > Alternate Configuration tab)', '(The book lists the first three.)'], 'b11');
T('wifisec', 'Valid security best practices to secure a wireless network', 'WPA3/WPA2-AES, strong passphrase, change router admin password, update firmware, disable WPS, guest network.', ['- Use **WPA3** (or **WPA2-AES**); never WEP or open', '- **Long, strong Wi-Fi passphrase**', '- **Change the router\'s default admin username/password**', '- **Update router firmware**', '- **Disable WPS** and remote management', '- Use a **guest network** for visitors and IoT', '- Change the default SSID (hiding it is **not** real security)'], 'b11');
T('forget', 'How to remove a known wireless network entry', 'Settings > Network & internet > Wi-Fi > Manage known networks > Forget (or netsh wlan delete profile).', ['**Settings > Network & internet > Wi-Fi > Manage known networks** > select it > **Forget**. Or from Quick Settings: right-click the network > Forget. Command line: `netsh wlan delete profile name="NetworkName"`.'], 'b11');
T('netcmds', 'Common command line utilities for diagnosing network difficulties', 'ipconfig, ping, tracert, nslookup, pathping, netstat, net, netsh.', ['- **ipconfig** (/all, /release, /renew, /flushdns): IP configuration', '- **ping**: is the host reachable? (ICMP)', '- **tracert**: path and each hop', '- **pathping**: tracert + packet loss per hop', '- **nslookup**: tests DNS name resolution', '- **netstat**: active connections and ports', '- **net**: shares, users, services', '- **netsh**: view/change network config'], 'b11');
T('staticinfo', 'The necessary pieces of information needed to statically assign an IP address', 'IP address, subnet mask, default gateway, DNS server(s).', ['1. **IP address**', '2. **Subnet mask** (or IPv6 prefix length)', '3. **Default gateway** (router)', '4. **Preferred (and alternate) DNS server**', 'Set in Settings > Network & internet > adapter > **IP assignment > Edit > Manual**.'], 'b11');
T('trouble8', 'The eight strategies for troubleshooting network connectivity issues', 'Troubleshooter, check physical/Wi-Fi, ipconfig, ping, isolate scope, restart modem/router, reset adapter, Network Reset.', ['A good order (book + class):', '1. Run the **Network troubleshooter** (Settings > System > Troubleshoot)', '2. Check the **physical connection** / Wi-Fi / airplane mode', '3. Check the **IP configuration** (`ipconfig /all`; 169.254 = DHCP problem)', '4. **ping** loopback, gateway, then an outside IP; **nslookup** for DNS', '5. **Isolate the problem**: all computers, a group, or just one?', '6. All affected: **restart the modem/internet device**; a group: **restart the router**', '7. One PC: **disable/enable the adapter** (repair the connection)', '8. Last resort: **Network Reset**', '*Compare with your class list in case your instructor numbers them differently.*'], 'b11');

/* ---------- Chapter 12 ---------- */
T('malware', 'Malware types and definitions', 'Virus, worm, Trojan, ransomware, spyware, adware, rootkit, keylogger, botnet, PUA.', ['- **Virus**: attaches to files, spreads when they run', '- **Worm**: spreads **on its own** across networks', '- **Trojan**: pretends to be useful software', '- **Ransomware**: encrypts files, demands payment', '- **Spyware / keylogger**: secretly records activity or keystrokes', '- **Adware**: forces ads', '- **Rootkit**: hides deep in the OS (boot-level)', '- **Botnet / bot**: PC remotely controlled with others', '- **PUA**: potentially unwanted app (bundled junk)'], 'b12');
T('updtypes', 'Types of Windows updates and how they differ', 'Quality (monthly), feature (yearly), driver, security intelligence (Defender, several times a day), optional/preview.', ['- **Quality updates**: **monthly** cumulative security and bug fixes (Patch Tuesday)', '- **Feature updates**: **yearly**, new version (22H2, 23H2), bigger download and restart', '- **Driver updates**: hardware drivers', '- **Security intelligence updates**: Defender **malware definitions**, several times a day', '- **Optional/preview** updates: early fixes and drivers you choose'], 'b12');
T('wumenu', 'Windows Update menu and advanced options', 'Pause updates, active hours, update history, Delivery Optimization, optional updates, Insider Program.', ['**Settings > Windows Update**:', '- **Pause updates** (1 to 5 weeks)', '- **Update history** (by KB number; uninstall updates)', '- **Advanced options**: **active hours** (no restarts while you work), receive updates for other Microsoft products, notify when restart needed, **optional updates**, **Delivery Optimization** (download updates from other PCs on your LAN or the internet), recovery', '- **Windows Insider Program**'], 'b12');
T('aslr', 'ASLR', 'Address Space Layout Randomization: loads code at random memory addresses so exploits can\'t predict them.', ['**Address Space Layout Randomization**: loads programs and system files at **random memory locations** each time, so an attacker can\'t predict where code lives. An **Exploit protection** mitigation.'], 'b12');
T('bitlocker', 'BitLocker', 'Full-volume encryption using the TPM; 48-digit recovery key (Pro and up).', ['Encrypts **entire drives**, using the **TPM** to protect the key. Pro and up (Home gets **device encryption**). Keep the **48-digit recovery key** safe (Microsoft account, AD, print). **BitLocker To Go** for USB drives.'], 'b12');
T('dep', 'DEP', 'Data Execution Prevention: blocks code from running in memory marked as data-only.', ['**Data Execution Prevention**: marks memory areas as **data only**, so code injected there (buffer overflow attacks) **can\'t run**. Hardware-enforced (NX bit).'], 'b12');
T('elam', 'ELAM', 'Early Launch Antimalware: antimalware driver loads first to check other boot drivers.', ['**Early Launch Antimalware**: Defender\'s ELAM driver **loads before all other boot drivers** and checks each one, blocking malicious drivers and **rootkits** before they start.'], 'b12');
T('measured', 'Measured boot', 'Firmware logs a hash of each boot component into the TPM so the boot can be verified later.', ['During startup, each component (firmware, boot loader, drivers, ELAM) is **measured (hashed) and recorded in the TPM**. The log can be checked (attestation) to prove the boot **wasn\'t tampered with**.'], 'b12');
T('uefi', 'UEFI', 'Modern firmware replacing BIOS; enables Secure Boot and GPT.', ['**Unified Extensible Firmware Interface**: replaces BIOS. Enables **Secure Boot** (only signed boot loaders run), GPT disks and faster startup. **Required by Windows 11.**'], 'b12');
T('smartscreen', 'SmartScreen', 'Defender reputation check that warns about malicious sites, downloads and unrecognized apps ("Windows protected your PC").', ['**Microsoft Defender SmartScreen** checks **websites, downloads and apps** against Microsoft\'s reputation lists and **warns or blocks** unknown/malicious ones ("Windows protected your PC"). Settings in Windows Security > App & browser control.'], 'b12');
T('tpm', 'TPM', 'Trusted Platform Module: tamper-resistant chip that stores encryption keys and measures boot; 2.0 required.', ['**Trusted Platform Module**: a **tamper-resistant chip** that **stores encryption keys** (BitLocker, Windows Hello) and **records boot measurements**. **TPM 2.0 is required** for Windows 11. Check with `tpm.msc`.'], 'b12');
T('hello', 'Windows Hello', 'Sign-in with face, fingerprint or a PIN tied to the device\'s TPM.', ['Passwordless sign-in: **face** (IR camera), **fingerprint**, or **PIN**. The PIN is **tied to this device\'s TPM**, so a stolen PIN is useless anywhere else.'], 'b10');
T('consent', 'Consent prompt', 'UAC prompt for administrators: just click Yes or No.', ['What an **administrator** sees: a **Yes/No** UAC box to approve elevation. No password needed.'], 'b12');
T('creds', 'Credentials prompt', 'UAC prompt for standard users: an admin must enter a password/PIN.', ['What a **standard user** sees: they must **enter an administrator\'s username and password (or PIN)** to continue.'], 'b12');
T('uacwarn', 'UAC warnings (Consent AND Credentials)', 'Consent = admin clicks Yes/No; Credentials = standard user must enter admin credentials.', ['- **Consent prompt**: shown to **admins**, click **Yes/No**', '- **Credentials prompt**: shown to **standard users**, type **admin credentials**', 'Both appear on the **secure desktop** (screen dims) so malware can\'t click them. Color hints: blue = Windows/verified publisher, yellow = unknown publisher.'], 'b12');
T('featupd', 'Feature updates', 'Yearly updates that install a new version of Windows with new features.', ['Released about **once a year**; install a **new version** (e.g. 22H2 → 23H2) with new features. Larger download, longer restart. Home/Pro releases supported 24 months, Enterprise 36.'], 'b12');
T('secintel', 'Security Intelligence Updates', 'Microsoft Defender malware definition updates, delivered several times a day.', ['**Microsoft Defender Antivirus definition (signature) updates**, delivered through Windows Update **several times a day** so Defender recognizes the newest threats.'], 'b12');
T('troublestrat', 'Troubleshooting strategies', 'Isolate the problem, check what changed, test simple fixes first, use built-in troubleshooters, document.', ['- **Identify and isolate**: who/what is affected, when it started, **what changed**', '- Try the **simplest fixes first** (restart, cables)', '- Use **built-in troubleshooters** and tools (ipconfig, ping, Event Viewer)', '- Change **one thing at a time** and test', '- **Escalate** or use last-resort resets; **document** the fix', '(For networks, see the eight strategies.)'], 'b11');
T('ipmanual', 'Components to manually set an IP address', 'IP address, subnet mask, default gateway, DNS server.', ['**IP address + subnet mask + default gateway + DNS server(s)**.'], 'b11');

/* ---------- Chapter 13 ---------- */
T('filerepo', 'Where the File Repository for drivers is found in C:', 'C:\\Windows\\System32\\DriverStore\\FileRepository', ['**C:\\Windows\\System32\\DriverStore\\FileRepository**. Each driver package gets its own subfolder (name ends in a 16-character ID). Everyone can Read & Execute; only admin-approved installers can write. Copy it before a clean reinstall.'], 'b13');
T('inf', 'The importance of the .inf file type in regards to drivers', 'Setup Information file required in every driver package; tells Windows how to install the driver.', ['Every driver package **must include a Setup Information (.inf) file**: a text file listing driver files, where they install, **registry settings** and version. Windows follows it during Plug and Play installs. .inf files live in **C:\\Windows\\Inf**. **Don\'t edit them.**'], 'b13');
T('kmode', 'Kernel-mode driver', 'Driver running with the same privileges as Windows; can crash the system; must be signed.', ['Runs at the **same privilege level as Windows itself**, so a bad one **can crash the system** (user-mode drivers can\'t). In Windows 11 **all kernel-mode drivers must be digitally signed** through Microsoft\'s Hardware Dev Center.'], 'b13');
T('drvstore', 'Where device driver packages are stored on C:', 'C:\\Windows\\System32\\DriverStore (installed files go to System32\\Drivers).', ['Packages: **C:\\Windows\\System32\\DriverStore** (in FileRepository). Installed driver files are copied to **C:\\Windows\\System32\\Drivers**. Drivers in the store are trusted and install without prompts.'], 'b13');
T('devmgr', 'Device Manager', 'devmgmt.msc: hierarchical list of all hardware, grouped by type, for drivers and troubleshooting.', ['**devmgmt.msc** or **Windows key+X**. Lists all hardware **by type**; yellow ! = problem, down arrow = disabled. Double-click a device for Properties (Update, Roll Back, Disable, Uninstall). Also a snap-in inside Computer Management.'], 'b13');
T('mmc', 'MMC', 'Microsoft Management Console: hosts snap-ins (.msc tools) such as Device Manager.', ['**Microsoft Management Console** hosts **snap-ins** (.msc), which do the actual work. A saved set of snap-ins is an **MMC console**. Run `mmc` to build a custom one. Device Manager, Services, Event Viewer, Disk Management are snap-ins.'], 'b16');
T('proptabs', 'Properties tabs, specifically Details & Events', 'Details = property list incl. Hardware IDs; Events = timeline of driver install/config events.', ['Tabs: General · Driver · **Details** · **Events** · Resources', '- **Details**: drop-down list of properties; **Hardware Ids** (VEN_ = vendor, DEV_ = device) identify unknown devices', '- **Events**: timestamped history of the device\'s **driver events** (installed, configured, service added); **View All Events** opens Event Viewer'], 'b13');
T('verifier', 'Verifier.exe', 'Driver Verifier: stress-tests drivers at startup and blue-screens on a bad one; verifier /reset turns it off.', ['**Driver Verifier**: run `verifier` from an **elevated** prompt > **Create Standard Settings**. Tests every driver **at startup**; a bad one causes a **blue screen naming the driver**. Turn off with **`verifier /reset`** (use **Safe Mode** if stuck).'], 'b13');
T('bthist', 'Bluetooth history', 'Named after King Harald "Bluetooth" Gormsson; created by Ericsson in 1994; Bluetooth SIG formed 1998.', ['Named after Danish king **Harald "Bluetooth" Gormsson**, who **united** Denmark and Norway, the way Bluetooth unites devices. **Ericsson** created it in **1994**; the **Bluetooth SIG** formed in **1998**. Logo = runes **H + B**. Short-range, **2.4 GHz**.'], 'gen');
T('pairing', 'Pairing', 'Linking two Bluetooth devices once (discoverable + Add device or Swift Pair) so they connect.', ['Make the device **discoverable**, then **Settings > Bluetooth & devices > Add device > Bluetooth**. **Swift Pair** pops up a Connect prompt automatically. Keyboards require **typing a code shown on screen**, so attackers can\'t sneak one in.'], 'b13');
T('rollback', 'Roll Back', 'Driver tab button that removes the latest manually updated driver and restores the previous one.', ['Device Manager > device > **Driver tab > Roll Back Driver**: removes the latest **manually** updated driver and restores the previous one. **Works in Safe Mode**; affects **only that device** (System Restore = whole PC). Grayed out if never updated or updated via Windows Update.'], 'b13');
T('signed', 'Signed driver', 'Driver digitally signed via Microsoft, proving the publisher; required for kernel-mode drivers.', ['Digitally signed via Microsoft (plus an **EV code-signing certificate**), proving **who published it** and that it wasn\'t altered. **Required for kernel-mode drivers.** Signed ≠ tested: **logo-certified** (passed Hardware Lab Kit tests) vs **attested** (vouched for). Windows Update drivers are signed by Microsoft.'], 'b13');

/* ---------- Chapter 14 ---------- */
T('perf5', 'The 5 top reasons the book gives for poor system performance', 'Inadequate hardware, defective hardware, outdated/flawed drivers, out-of-control processes/services, malware.', ['1. **Inadequate hardware resources**', '2. **Defective hardware** (memory, disk errors)', '3. **Outdated or flawed device drivers**', '4. **Out-of-control processes or services** (100% CPU, memory leaks)', '5. **Malware**'], 'b14');
T('sysinfo', 'System Information', 'msinfo32: detailed hardware/software inventory (BIOS mode, Secure Boot, drivers...).', ['**msinfo32**: full inventory: System Summary (OS, BIOS version/mode **UEFI or Legacy**, **Secure Boot** state, RAM), **Hardware Resources**, **Components**, **Software Environment** (drivers, services, startup programs). Can export a report.'], 'b14');
T('tmtabs', 'The tabs of Task Manager and what each connects you to', 'Processes, Performance (> Resource Monitor), App history, Startup apps, Users, Details, Services (> Services console).', ['- **Processes**: apps and background processes, End task, Efficiency mode', '- **Performance**: CPU, memory, disk, network, GPU graphs; link to **Resource Monitor**', '- **App history**: past resource use per app', '- **Startup apps**: enable/disable sign-in apps', '- **Users**: per-user resource use, disconnect/sign out', '- **Details**: processes by .exe/PID; priority, affinity, **Open file location**', '- **Services**: start/stop; **Open Services** opens services.msc'], 'b14');
T('systeminfo', 'Systeminfo', 'Command-line summary: OS version, install date, last boot time, RAM, hotfixes, network cards.', ['Type **`systeminfo`** in a command prompt: OS name/version/build, **original install date**, **system boot time**, BIOS, RAM, domain, **hotfixes (KBs)** and network adapters. Works on remote PCs with /s.'], 'b14');
T('wmic', 'WMIC', 'Windows Management Instrumentation Command-line: queries system info (deprecated; use PowerShell Get-CimInstance).', ['**Windows Management Instrumentation Command-line**: queries WMI for system details, e.g. `wmic bios get serialnumber`, `wmic cpu get name`. **Deprecated/removed** in newer builds; PowerShell `Get-CimInstance` replaces it.'], 'b14');
T('syspage', 'Link to the System page and what information is found there', 'Settings > System > About: device name, CPU, RAM, device/product ID, system type, edition, version, build.', ['**Settings > System > About** (also Windows key+Pause/Break or right-click Start > System):', '- **Device specifications**: device name, **processor**, **installed RAM**, device ID, product ID, **system type** (64-bit), pen/touch', '- **Windows specifications**: **edition**, **version**, install date, **OS build**', '- Related links: domain/workgroup, **System protection**, **Advanced system settings**, Rename this PC'], 'b14');
T('powermgmt', 'The mouse-click trail to get to Power Management', 'Settings > System > Power & battery (power mode, screen and sleep).', ['**Start > Settings > System > Power & battery**: **Power mode** (best efficiency / balanced / best performance), **Screen and sleep** timeouts, **Battery saver**. (Device-level: Device Manager > device > **Power Management** tab; classic: Control Panel > Power Options.)'], 'b14');
T('appinfo', 'Options in the Application Information Properties dialog (right-click a service)', 'Tabs: General (startup type, start/stop, parameters), Log On, Recovery, Dependencies.', ['Services > right-click **Application Information** > **Properties**:', '- **General**: service name, description, **path to executable**, **startup type** (Automatic, Automatic (Delayed Start), Manual, Disabled), **Start/Stop/Pause/Resume**, start parameters', '- **Log On**: which account it runs as', '- **Recovery**: what to do if it fails (restart service, run a program, restart PC)', '- **Dependencies**: services it needs and services that need it'], 'b14');
T('svcwarn', 'What to know about changing a service configuration (Task Manager > Services > Open Services > Properties)', 'Don\'t change services you don\'t understand; changes can break Windows features. Note the default first.', ['**Be very careful.** Disabling or changing a service you don\'t fully understand can **break Windows features or stop the PC from working** (dependencies). **Write down the default** before you change anything, change one at a time, and leave most services at their defaults. Example: **Application Information** is what lets apps elevate through **UAC**: disable it and admin tasks stop working.'], 'b14');
T('tmdev', 'Task Manager\'s developer', 'Dave Plummer, a Microsoft engineer, wrote the original Task Manager in the 1990s.', ['**Dave Plummer**, a Microsoft software engineer, wrote the original Task Manager (Windows NT 4.0, 1990s). He now talks about it on his YouTube channel *Dave\'s Garage*.'], 'gen');

/* ---------- Linux unit ---------- */
T('lx_kernel', 'Linux is the kernel', 'Linux is the core of the OS that lets software use the hardware; everything else is built around it.', ['Linux is the **kernel**, the core that lets software use the hardware. Distros build the rest (desktop, apps) around it. Car analogy: the engine vs the whole customized car.'], 'class');
T('lx_open', 'Open source', 'Source code is freely available to view, modify and share, which makes most distros free.', ['**Open source**: anyone can **view, modify and distribute** the code. Community-driven, constantly improved, and most **distros are free**.'], 'class');
T('lx_benefit', 'Benefits of Linux', 'Free, secure, flexible/customizable, runs well on old hardware, developer-friendly.', ['**Cost** (free) · **Security** (fast community patching) · **Flexibility & customization** · **Performance** on older hardware · **Developer-friendly**'], 'class');
T('lx_draw', 'Drawbacks of Linux', 'Learning curve (CLI), software compatibility, hardware driver support.', ['**Learning curve** (the command line) · **Software compatibility** (some commercial apps missing) · **Hardware driver support** for niche devices'], 'class');
T('lx_where', 'Where Linux is used', 'Servers and cloud, embedded systems (Android, routers, TVs), supercomputers, desktops.', ['**Servers** (most web, cloud and database servers) · **Embedded** (Android, routers, smart TVs, industrial controls) · **Supercomputers** (it dominates) · growing **desktop** use'], 'class');
T('lx_distros', 'Popular Linux distributions', 'Ubuntu, Mint, Debian, Fedora, Pop!_OS, Arch, BlackArch.', ['- **Ubuntu**: most popular, beginner-friendly', '- **Linux Mint**: based on Ubuntu, traditional desktop', '- **Debian**: the "mother" of Ubuntu, stable', '- **Fedora**: leading-edge, developer tools', '- **Pop!_OS**: System76, gaming and productivity', '- **Arch**: build it yourself, for experts', '- **BlackArch**: white-hat hacking/security tools'], 'class');
T('lx_why', 'Why Linux is popular', 'Community support, ease of use (Ubuntu/Mint), growing software, regular updates, runs well in VMs.', ['Big **community support** · **ease of use** (Ubuntu, Mint) · growing **software availability** · **regular updates** · **runs easily in VMs** (small footprint)'], 'class');
T('lx_perm', 'drwxr-xr-x (the permission string)', 'File type, then rwx for owner, group, others: here a directory, owner full, group and others read+execute.', ['From `ls -l`. Four parts:', '- **1st character: type**: `d` directory, `-` file, `l` link', '- **Next 3: owner (user)**: `rwx`', '- **Middle 3: group**: `r-x`', '- **Last 3: others**: `r-x`', 'So drwxr-xr-x: a directory; owner has full access; group and others can list and enter it but not create, rename or delete inside.'], 'class');
T('lx_rwx', 'r, w, x and the octal values', 'r = 4 read, w = 2 write, x = 1 execute, 0 none; add them per group.', ['**r = 4** (read) · **w = 2** (write) · **x = 1** (execute) · **0** = none. Add per group: **7** rwx · **6** rw- · **5** r-x · **4** r--. Three digits = **user, group, others**.'], 'class');
T('lx_chmod', 'chmod', 'Change mode: changes permissions, symbolic (u+x) or numeric (755).', ['**Change mode**. Two ways:', '- **Symbolic**: `chmod u+x file` (add execute for owner), `g-w` (remove group write), `o=r` (others read only), `a+rw` (all)', '- **Numeric (octal)**: `chmod 755 file` = rwxr-xr-x; `chmod 644 file` = rw-r--r--'], 'class');
T('lx_chown', 'chown', 'Change owner: sets the user (and optionally group) owner; usually needs sudo.', ['**Change owner**: `sudo chown newuser file`, or `sudo chown newuser:newgroup file` for both. Usually needs **sudo**.'], 'class');
T('lx_chgrp', 'chgrp', 'Change group: changes only the group owner of a file.', ['**Change group** only: `sudo chgrp newgroup file`.'], 'class');
T('lx_script', 'Purpose of Linux scripting', 'Automate tasks by combining commands and logic into one executable file (a script).', ['**Automate tasks and streamline operations** by putting a sequence of commands and logic into **one executable file**. Uses: task automation (backups, log cleanup, updates, user management), system administration, process control, customization, **error reduction and consistency**, batch processing, monitoring and alerts.'], 'class');
T('lx_shells', 'Shell vs non-shell script languages', 'Shell: Bash, Zsh, Dash. Non-shell: Python, Perl, Ruby, PowerShell, Tcl, Lua, Node.js, Awk, Sed.', ['- **Shell**: **Bash, Zsh, Dash**', '- **Non-shell**: Python, Perl, Ruby, PowerShell for Linux, Tcl, Lua, Node.js, Awk, Sed'], 'class');
T('lx_shell', 'Shell', 'The command-line interpreter users type into (Bash, Zsh).', ['The **command-line interpreter** you type commands into (Bash, Zsh). A **shell script** is a file of commands the shell runs.'], 'class');
T('lx_shebang', 'Shebang (#!)', 'First line of a script naming the interpreter, e.g. #!/bin/bash.', ['The **first line** of a script, telling Linux **which interpreter** runs it: `#!/bin/bash`.'], 'class');
T('lx_bash', 'Bash', 'Bourne Again Shell: the most widely used Linux shell.', ['**Bourne Again Shell**: the default, widely used, powerful shell on most distros.'], 'class');
T('lx_cli', 'CLI', 'Command Line Interface: text-based way to control the OS.', ['**Command Line Interface**: controlling the system by **typing text commands** (vs a GUI).'], 'class');
T('lx_pipe', 'Pipe (|)', 'Sends the output of one command into another as input.', ['Connects commands: **output of the left becomes input of the right**. `ls -l | less`, `ps aux | grep firefox`.'], 'class');
T('lx_redir', 'Redirection (>, >>, <)', '> overwrite output to a file, >> append, < take input from a file.', ['- **>** write output to a file (**overwrite**): `ls > list.txt`', '- **>>** **append** to a file', '- **<** take **input from** a file', 'Lab example: `history > ~/Desktop/mysessionhistory1.txt`.'], 'class');
T('lx_var', 'Variables', 'Named storage in a script: MYVAR="hello", used as $MYVAR.', ['Store data: `MYVAR="hello"` (no spaces around =), use with **$**: `echo $MYVAR`.'], 'class');
T('lx_pos', 'Positional parameters ($1, $2)', 'Arguments passed to a script: $1 is the first, $2 the second.', ['Arguments given when running a script: `./backup.sh Documents` makes **$1** = Documents. **$2** is the second, and so on.'], 'class');
T('lx_loops', 'Loops (for, while)', 'Repeat a block of code: for each item, or while a condition is true.', ['**for**: repeat for each item (`for f in *.txt; do ... done`). **while**: repeat while a condition is true.'], 'class');
T('lx_if', 'Conditional statements (if, else, elif)', 'Run code only when a condition is true.', ['Run code **based on conditions**: `if [ -f file ]; then ... elif ...; else ...; fi`.'], 'class');
T('lx_func', 'Functions', 'Reusable named blocks of code inside a script.', ['**Reusable blocks** of code you name once and call many times in a script.'], 'class');
T('lx_comment', 'Comments (#)', 'Lines starting with # are ignored; used to explain the script.', ['Lines starting with **#** are **ignored** by the interpreter: notes for humans. (The #! shebang on line 1 is the exception.)'], 'class');
T('lx_root', 'Root', 'The superuser account with full system access.', ['The **superuser** with **full access**. Use **sudo** to run single commands as root instead of logging in as root.'], 'class');
T('lx_distro', 'Distro', 'A specific distribution of Linux (Ubuntu, Fedora, Debian).', ['A **distribution**: the Linux kernel plus a chosen set of software, desktop and package manager (Ubuntu, Fedora, Debian).'], 'class');
T('lx_env', 'Environment variables', 'Variables that affect how processes and programs behave ($HOME, $PATH).', ['System-wide variables that **affect how programs behave**: **$HOME** (your home folder), **$PATH** (where commands are found), $USER. `echo $HOME`.'], 'class');

/* Linux commands (Top 25 + lab) */
const LXC = [
  ['ls', 'List files and directories (-l long listing with permissions, -a show hidden).'], ['cd', 'Change directory (cd .. up one, cd ~ or cd home).'], ['pwd', 'Print working directory: shows where you are.'],
  ['mkdir', 'Make a directory (-p creates nested folders).'], ['rm', 'Remove files (-r recursive, -f force; rm -rf deletes a folder and everything in it, permanently).'], ['cp', 'Copy files (-r for directories).'],
  ['mv', 'Move or rename files.'], ['rmdir', 'Remove an empty directory (refuses if it has files).'], ['touch', 'Create an empty file (or update its timestamp).'],
  ['cat', 'Display a file\'s contents (no editing).'], ['echo', 'Print text or a variable ($HOME).'], ['grep', 'Search inside files for a pattern.'],
  ['find', 'Search for files by name, size, type.'], ['sudo', 'Run a command as superuser (root).'], ['ps', 'List running processes (ps aux = all).'],
  ['top', 'Live view of processes sorted by CPU.'], ['kill', 'Send a signal to a process by PID, usually to end it.'], ['df', 'Disk free space (-h human-readable).'],
  ['du', 'Disk space used by files/folders (-h).'], ['history', 'List previously typed commands.'], ['man', 'Show the manual page for a command.'],
  ['tar', 'Create (-cvf) or extract (-xvf) archives.'], ['systemctl', 'Start, stop, restart or check system services.'], ['whoami', 'Show your username.'],
  ['nano', 'Simple text editor (Ctrl+S save, Ctrl+X exit).'], ['script', 'Record the terminal session to a file (exit or Ctrl+D stops).'], ['useradd', 'Create a user account (with sudo).'],
  ['passwd', 'Set or change a user\'s password.'], ['groupadd', 'Create a group.'], ['usermod', 'Modify a user; -aG adds them to a group.'],
  ['id', 'Show a user\'s UID, GID and groups.'], ['userdel', 'Delete a user account.'], ['groupdel', 'Delete a group.'],
  ['apt', 'Install/update software packages on Debian/Ubuntu (sudo apt install vim).'], ['less', 'Page through output one screen at a time (q quits).'], ['ifconfig', 'Old command to show network interfaces (IP, netmask, MAC).'],
  ['ip address', 'Modern replacement for ifconfig: shows interface info.'], ['ping', 'Test reachability of a host (Ctrl+C stops).'], ['traceroute', 'Show the path packets take to a host.'],
  ['netstat', 'Show network connections and ports (-tulnp); ss is the modern replacement.']
];
LXC.forEach(([c, d]) => T('cmd_' + c.replace(/\W/g, '_'), c, d, [d], 'class'));
T('lx_etc', '/etc/passwd and /etc/group', 'Files where Linux stores user accounts (/etc/passwd) and groups (/etc/group).', ['**/etc/passwd** lists **user accounts**; **/etc/group** lists **groups**. They\'re **files**, not folders: view with `cat`, `less` or `vim` (not `cd`). Your new user appears at the bottom.'], 'class');
T('lx_case', 'Case sensitivity', 'Linux treats ls and LS (and File.txt and file.txt) as different.', ['Linux is **case-sensitive**: `ls` ≠ `LS`, and `Batman.txt` ≠ `batman.txt`. Type commands exactly.'], 'class');

/* ---------- Windows reviews, one per chapter ----------
   Each chapter combines its quiz review and the unit exam items for that chapter.
   SHEETS records which review sheet(s) each item came from, so the review shows "Quiz 8 · Unit Exam 3" badges. */
